59	  // Demoting an owner is fine while another owner exists.
60	  it("allows demoting an owner when another owner remains", async () => {
61	    const tenant = await createTenant("member-second-owner", "growth");
62	    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
